#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; cin>>n;
    vector<int> ks(n);
    vector<vector<pair<int,int>>> raw(n);
    int tot=0;
    for(int i=0;i<n;i++){cin>>ks[i];raw[i].resize(ks[i]);for(int j=0;j<ks[i];j++)cin>>raw[i][j].first>>raw[i][j].second;tot+=ks[i];}
    auto tr=[](const vector<pair<int,int>>&c,int r,int f)->vector<pair<int,int>>{
        vector<pair<int,int>> res;
        for(auto[x,y]:c){int tx=x,ty=y;if(f)tx=-tx;for(int i=0;i<r;i++){int nx=-ty,ny=tx;tx=nx;ty=ny;}res.push_back({tx,ty});}
        int mx=INT_MAX,my=INT_MAX;for(auto[x,y]:res){mx=min(mx,x);my=min(my,y);}
        for(auto&[x,y]:res){x-=mx;y-=my;}sort(res.begin(),res.end());return res;};
    struct Or{vector<pair<int,int>>c;int w,h,r,f;};
    vector<vector<Or>> ori(n);
    for(int i=0;i<n;i++){set<vector<pair<int,int>>>seen;for(int f=0;f<2;f++)for(int r=0;r<4;r++){auto c=tr(raw[i],r,f);if(!seen.count(c)){seen.insert(c);int mw=0,mh=0;for(auto[x,y]:c){mw=max(mw,x);mh=max(mh,y);}ori[i].push_back({c,mw+1,mh+1,r,f});}}}
    vector<int> ord(n);iota(ord.begin(),ord.end(),0);sort(ord.begin(),ord.end(),[&](int a,int b){return ks[a]>ks[b];});
    int ba=INT_MAX;vector<int> bx(n),by(n),br(n),bf(n);int bW=0,bH=0;
    int mxpw=0;for(int i=0;i<n;i++)for(auto&o:ori[i])mxpw=max(mxpw,o.w);
    for(int W=mxpw;W<=tot&&W<=300;W++){
        vector<int>sky(W,0);
        vector<int>px(n),py(n),pr(n),pf(n);bool ok=true;int cH=0;
        vector<vector<bool>>grid(W,vector<bool>(tot+1,false));
        for(int idx=0;idx<n;idx++){int i=ord[idx];int bs=INT_MAX;int bxi=-1,byi=-1,boi=-1;
            for(int oi=0;oi<(int)ori[i].size();oi++){auto&o=ori[i][oi];if(o.w>W)continue;
                for(int x=0;x<=W-o.w;x++){int mn=0;for(auto[cx,cy]:o.c)mn=max(mn,sky[x+cx]-cy);if(mn<0)mn=0;
                    bool gd=true;for(auto[cx,cy]:o.c){int gy=mn+cy;if(gy>=tot+1||grid[x+cx][gy]){gd=false;break;}}
                    if(!gd)continue;int mh=0;for(auto[cx,cy]:o.c)mh=max(mh,mn+cy+1);
                    int sc=max(cH,mh)*10000+mh*100+x;if(sc<bs){bs=sc;bxi=x;byi=mn;boi=oi;}}}
            if(boi<0){ok=false;break;}auto&o=ori[i][boi];px[i]=bxi;py[i]=byi;pr[i]=o.r;pf[i]=o.f;
            for(auto[cx,cy]:o.c){grid[bxi+cx][byi+cy]=true;sky[bxi+cx]=max(sky[bxi+cx],byi+cy+1);cH=max(cH,byi+cy+1);}}
        if(!ok)continue;int area=W*cH;if(area<ba){ba=area;bW=W;bH=cH;bx=px;by=py;br=pr;bf=pf;}}
    cout<<bW<<" "<<bH<<"\n";for(int i=0;i<n;i++)cout<<bx[i]<<" "<<by[i]<<" "<<br[i]<<" "<<bf[i]<<"\n";
}
